mapper.select:
SELECT a.id AS id, a.title AS title, a.cover AS cover, a.summary AS summary, a.category_id AS categoryId, c.name AS categoryName, a.view_count AS viewCount, a.comment_count AS commentCount, a.like_count AS likeCount, a.type AS type, a.is_top AS isTopRaw, a.published_at AS publishedAt, a.status AS status, a.create_time AS createTime, a.update_time AS updateTime FROM t_article a LEFT JOIN t_category c ON c.id = a.category_id AND c.deleted = 0 WHERE a.deleted = 0
AND a.status = #{param.status}
AND a.type = #{param.type}
AND ( a.title LIKE CONCAT('%', #{param.keyword}, '%') OR a.summary LIKE CONCAT('%', #{param.keyword}, '%') )
ORDER BY IFNULL(a.is_top, 0) DESC, CASE WHEN a.published_at IS NULL THEN 1 ELSE 0 END, a.published_at DESC, a.create_time DESC, a.id DESC
